\DeclareSymbolFont{linotext}{T1}{linotext}{m}{n}
\DeclareSymbolFontAlphabet{\mathLINOTEXT}{linotext}
\begin{document}$${\mathrm{\eta=}}{{{\mathrm{m\times\,c\,\times}}\left({{{\mathrm{T}}_{{\mathrm{max}}}}{\mathrm{-}}{{\mathrm{T}}_{{\mathrm{sur}}}}}\right)}\over{{\mathrm{I\times}}\left({{\mathrm{1-1}}{{\mathrm{0}}^{{\mathrm{-}}{{\mathrm{A}}_{{\mathrm{808}}}}}}}\right){\mathrm{\times}}{{\mathrm{T}}_{\mathrm{s}}}}}$$\end{document}
